/* Chelo compact KPK WDL bitbase. Generated by benchmarks/generate-kpk-bitbase.py.
 * 24,576 bytes; 1 bit per canonical (side-to-move, pawn, king, king) state.
 * Theoretical WDL ignores the 50-move counter and repetition history.
 */
(() => {
  'use strict';
  const root=typeof self!=='undefined'?self:globalThis;
  const encoded='';
  const binary=atob(encoded),table=new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++)table[i]=binary.charCodeAt(i);
  root.CHESSLING_KPK_WDL=table;
})();
